-- Checklist dọn phòng mặc định theo "Checklist dọn phòng 10 phút" (Unixstay, Tờ A + mẫu chụp ảnh).
-- Thay mẫu mặc định đã lưu (nếu có); mẫu riêng của từng cơ sở giữ nguyên.
UPDATE "checklist_templates" SET "steps" = '[{"id":"b1","item":"Vỏ chăn-ga-gối thay mới: không vết bẩn, không tóc, không hôi, nhăn dưới 40%","needPhoto":true,"hint":"Ảnh cận cảnh giường: đứng cuối giường, chụp chéo 30–45° dọc mặt giường lên đến gối, thấy rõ ga và gối.","sample":null},{"id":"b2","item":"Điều hòa: bật, mát rõ sau 5 phút · điều khiển có pin","needPhoto":true,"hint":"Chụp cận remote hoặc cục lạnh đang hiện đèn báo bật và nhiệt độ cài đặt.","sample":null},{"id":"b3","item":"Wifi vào được, máy chiếu/TV mở Netflix xem thử 1 phim","needPhoto":true,"hint":"Bật máy → mở Netflix → chọn phim bấm play, chụp màn hình đang phát. Theo mẫu cần quay video 10–15 giây, gửi qua kênh của cơ sở.","sample":null},{"id":"b4","item":"Bếp từ, ấm siêu tốc, máy hút mùi: bật thử, có hoạt động","needPhoto":true,"hint":"Ảnh toàn cảnh khu bếp: đứng đối diện, chụp ngang tầm mắt lấy đủ 3 thiết bị và mặt bếp trong một khung.","sample":null},{"id":"b5","item":"Tủ lạnh: làm lạnh, sạch, không còn đồ thừa","needPhoto":true,"hint":"Mở hết cửa tủ lạnh, đứng thẳng phía trước chụp toàn bộ khoang bên trong.","sample":null},{"id":"b6","item":"Giấy vệ sinh: 01 cuộn (cuộn đang dùng dưới ½ thì thêm 1 cuộn mới)","needPhoto":false,"hint":null,"sample":null},{"id":"b7","item":"Dầu gội & sữa tắm: còn trên ⅓ bình (dưới ⅓ thì đổ đầy)","needPhoto":false,"hint":null,"sample":null},{"id":"b8","item":"Bàn chải 2 cái còn nguyên túi · kem đánh răng","needPhoto":false,"hint":null,"sample":null},{"id":"b9","item":"Khăn tắm 2 cái sạch, không ẩm ướt, không hôi","needPhoto":true,"hint":"Một ảnh chung đồ dùng nhà tắm: giấy vệ sinh, dầu gội & sữa tắm, bàn chải + kem, khăn tắm — đếm được rõ số lượng.","sample":null},{"id":"b10","item":"Bồn rửa, bồn cầu, sàn: sạch, khô, không tóc, không mùi hôi","needPhoto":true,"hint":"Ảnh toàn cảnh nhà tắm: đứng tại cửa, lấy đủ bồn cầu, bồn rửa và sàn trong một khung.","sample":null},{"id":"b11","item":"Lòng bồn cầu: sạch, không ố vàng","needPhoto":true,"hint":"Mở nắp, chụp từ trên xuống nhìn thẳng vào lòng bồn, đủ sáng. Đây là chỗ khách hay khiếu nại nhất.","sample":null},{"id":"b12","item":"Nước nóng vòi sen: mở thử, có nước nóng","needPhoto":true,"hint":"Mở vòi sen hết cỡ nóng, chụp thấy rõ hơi nước. Theo mẫu cần quay video 10 giây (hứng tay, nói \"nước đã nóng\"), gửi qua kênh của cơ sở.","sample":null},{"id":"b13","item":"Khoá cửa dễ khoá, không kẹt, không hỏng · khoá lại, cất chìa vào hộp khoá","needPhoto":true,"hint":"Mở nắp hộp khoá, chụp rõ số phòng trên hộp và trên chìa, lấy được cửa phòng đã đóng kín phía sau.","sample":null},{"id":"b14","item":"Báo cáo: ảnh toàn cảnh phòng lúc rời đi · ghi vấn đề phát hiện vào ghi chú (nếu có)","needPhoto":true,"hint":"Đứng tại cửa ra vào, bật đủ đèn, chụp thẳng vào trong lấy đủ giường và phần lớn phòng. Mục nào không đạt phải xử lý xong trước khi giao phòng.","sample":null}]'::jsonb, "updated_at" = now()
WHERE "type" = 'CLEANING' AND "property_id" IS NULL;--> statement-breakpoint
-- Phòng chưa bắt đầu dọn (chưa tick, chưa có ảnh) ở cơ sở dùng mẫu mặc định: đổi sang checklist mới.
UPDATE "checklist_results" cr SET "results" = '[{"item":"Vỏ chăn-ga-gối thay mới: không vết bẩn, không tóc, không hôi, nhăn dưới 40%","done":false,"needPhoto":true,"hint":"Ảnh cận cảnh giường: đứng cuối giường, chụp chéo 30–45° dọc mặt giường lên đến gối, thấy rõ ga và gối."},{"item":"Điều hòa: bật, mát rõ sau 5 phút · điều khiển có pin","done":false,"needPhoto":true,"hint":"Chụp cận remote hoặc cục lạnh đang hiện đèn báo bật và nhiệt độ cài đặt."},{"item":"Wifi vào được, máy chiếu/TV mở Netflix xem thử 1 phim","done":false,"needPhoto":true,"hint":"Bật máy → mở Netflix → chọn phim bấm play, chụp màn hình đang phát. Theo mẫu cần quay video 10–15 giây, gửi qua kênh của cơ sở."},{"item":"Bếp từ, ấm siêu tốc, máy hút mùi: bật thử, có hoạt động","done":false,"needPhoto":true,"hint":"Ảnh toàn cảnh khu bếp: đứng đối diện, chụp ngang tầm mắt lấy đủ 3 thiết bị và mặt bếp trong một khung."},{"item":"Tủ lạnh: làm lạnh, sạch, không còn đồ thừa","done":false,"needPhoto":true,"hint":"Mở hết cửa tủ lạnh, đứng thẳng phía trước chụp toàn bộ khoang bên trong."},{"item":"Giấy vệ sinh: 01 cuộn (cuộn đang dùng dưới ½ thì thêm 1 cuộn mới)","done":false,"needPhoto":false},{"item":"Dầu gội & sữa tắm: còn trên ⅓ bình (dưới ⅓ thì đổ đầy)","done":false,"needPhoto":false},{"item":"Bàn chải 2 cái còn nguyên túi · kem đánh răng","done":false,"needPhoto":false},{"item":"Khăn tắm 2 cái sạch, không ẩm ướt, không hôi","done":false,"needPhoto":true,"hint":"Một ảnh chung đồ dùng nhà tắm: giấy vệ sinh, dầu gội & sữa tắm, bàn chải + kem, khăn tắm — đếm được rõ số lượng."},{"item":"Bồn rửa, bồn cầu, sàn: sạch, khô, không tóc, không mùi hôi","done":false,"needPhoto":true,"hint":"Ảnh toàn cảnh nhà tắm: đứng tại cửa, lấy đủ bồn cầu, bồn rửa và sàn trong một khung."},{"item":"Lòng bồn cầu: sạch, không ố vàng","done":false,"needPhoto":true,"hint":"Mở nắp, chụp từ trên xuống nhìn thẳng vào lòng bồn, đủ sáng. Đây là chỗ khách hay khiếu nại nhất."},{"item":"Nước nóng vòi sen: mở thử, có nước nóng","done":false,"needPhoto":true,"hint":"Mở vòi sen hết cỡ nóng, chụp thấy rõ hơi nước. Theo mẫu cần quay video 10 giây (hứng tay, nói \"nước đã nóng\"), gửi qua kênh của cơ sở."},{"item":"Khoá cửa dễ khoá, không kẹt, không hỏng · khoá lại, cất chìa vào hộp khoá","done":false,"needPhoto":true,"hint":"Mở nắp hộp khoá, chụp rõ số phòng trên hộp và trên chìa, lấy được cửa phòng đã đóng kín phía sau."},{"item":"Báo cáo: ảnh toàn cảnh phòng lúc rời đi · ghi vấn đề phát hiện vào ghi chú (nếu có)","done":false,"needPhoto":true,"hint":"Đứng tại cửa ra vào, bật đủ đèn, chụp thẳng vào trong lấy đủ giường và phần lớn phòng. Mục nào không đạt phải xử lý xong trước khi giao phòng."}]'::jsonb
FROM "tasks" t
WHERE t."id" = cr."task_id" AND t."type" = 'CLEANING' AND t."status" = 'TODO' AND cardinality(t."photo_urls") = 0
  AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(cr."results") e WHERE coalesce((e->>'done')::boolean, false) OR coalesce(e->>'photo', '') <> '')
  AND NOT EXISTS (SELECT 1 FROM "checklist_templates" ct WHERE ct."type" = 'CLEANING' AND ct."property_id" = t."property_id");
